 for(const x of [-.085,.085]){add(sphere,new T.MeshStandardMaterial({color:'#f1e5d1'}),[x,2.18,.207],[.046,.028,.022]);add(sphere,new T.MeshStandardMaterial({color:'#2e454a'}),[x,2.179,.227],[.018,.021,.009]);add(sphere,skin,[Math.sign(x)*.24,2.15,0],[.035,.075,.045]);}
 add(sphere,skin,[0,2.12,.235],[.035,.055,.047]);add(sphere,new T.MeshStandardMaterial({color:'#a77767'}),[0,2.025,.213],[.065,.009,.01]);
