 const glasses=new T.Group();g.add(glasses);for(const x of [-.09,.09])add(sphere,new T.MeshStandardMaterial({color:'#263c45',metalness:.5,roughness:.15}),[x,2.19,.23],[.079,.046,.016],glasses);add(cylinder,new T.MeshStandardMaterial({color:'#39494a'}),[0,2.19,.237],[.008,.12,.008],glasses).rotation.z=Math.PI/2;
 function bone(mat,r){return add(cylinder,mat,[0,0,0],[r,1,r]);}const arms=[];for(const side of [-1,1]){const upper=bone(cloth,.105),fore=bone(skin,.079),hand=new T.Group();hand.name=side===-1?'Reeling hand':'Rod hand';g.add(hand);add(sphere,skin,[0,0,0],[.08,.11,.045],hand);for(let i=0;i<4;i++){const finger=add(sphere,skin,[-.047+i*.031,-.09,.025],[.016,.055,.017],hand);finger.rotation.x=.6;}add(sphere,skin,[.085,-.02,.03],[.026,.055,.023],hand).rotation.z=-.6;arms.push({side,upper,fore,hand});}
 const rod=new T.Group();rod.name='Bending rod';g.add(rod);const rodMat=new T.MeshStandardMaterial({color:'#879383',map:surfaceTexture('metal'),metalness:.35,roughness:.4}),rodSegments=Array.from({length:14},()=>{const m=new T.Mesh(new T.CylinderGeometry(.014,.019,1,8),rodMat);rod.add(m);return m;});const guides=Array.from({length:7},(_,i)=>{const m=add(new T.TorusGeometry(.033-i*.0028,.006,6,14),new T.MeshStandardMaterial({color:'#d8d4bc',metalness:.8,roughness:.2}),[0,0,0],[1,1,1],rod);return m;});const grip=add(cylinder,new T.MeshStandardMaterial({color:'#b4956f',map:surfaceTexture('cork'),roughness:.9}),[0,0,0],[.039,.4,.039],rod);const spool=add(new T.TorusGeometry(.1,.025,8,20),new T.MeshStandardMaterial({color:'#a8b8ad',metalness:.7,roughness:.25}),[0,0,0],[1,1,1],rod);const crank=add(cylinder,new T.MeshStandardMaterial({color:'#a6b5aa',metalness:.6}),[0,0,0],[.014,.18,.014],rod);
