 function refresh(character=state.character){skin.color.set(SKINS[character?.skin||0]);hairMat.color.set(HAIRS[character?.hair||0]);cloth.color.set(APPAREL.find(a=>a.id===state.outfit.shirt)?.color||'#c6bda3');pants.color.set(APPAREL.find(a=>a.id===state.outfit.pants)?.color||'#667d79');shoes.color.set(APPAREL.find(a=>a.id===state.outfit.shoes)?.color||'#66594b');hat.visible=state.outfit.hat!=='hat0';for(const o of hat.children)o.material.color.set(APPAREL.find(a=>a.id===state.outfit.hat)?.color||'#bfa27a');glasses.visible=state.outfit.glasses!=='glasses0';hair.scale.y=character?.style===2?.16:.24;hair.rotation.z=character?.style===1?.08:0;for(const tuft of hairTufts){tuft.visible=character?.style!==2;tuft.scale.y=character?.style===1?.065:.1;tuft.rotation.z=character?.style===1?.45:-tuft.position.x*1.5;}}
 function update(dt,t,mode,tension=0,pull=0,charge=0){if(mode!==lastMode){lastMode=mode;modeTime=0;}else modeTime+=dt;if(mode==='charging')lastCharge=charge;chargeBlend+=((mode==='charging'?charge:mode==='waiting'?lastCharge*(1-Math.min(1,modeTime/.55)):0)-chargeBlend)*(1-Math.exp(-dt*14));const held=['catch','landing'].includes(mode);firstBlend+=((state.cameraMode==='first'&&!held&&mode!=='create'&&mode!=='title'?1:0)-firstBlend)*(1-Math.exp(-dt*5));pose+=(Number(held)-pose)*(1-Math.exp(-dt*5));if(mode==='reeling'||mode==='landing')reelPhase+=dt*(mode==='landing'?18:9);const breathe=Math.sin(t*1.7)*.01;const left=new T.Vector3(.4-firstBlend*.24,1.57+pose*.9+breathe+firstBlend*.9,.46-pose*.05+firstBlend*.75),right=new T.Vector3(-.05+firstBlend*.1,1.43+pose*.52+Math.sin(reelPhase)*.075+firstBlend*1.0,.47+Math.cos(reelPhase)*.08+firstBlend*.75);left.y+=chargeBlend*.26;left.z-=chargeBlend*.70;right.y+=chargeBlend*.18;right.z-=chargeBlend*.66;const hands=[right,left];for(let i=0;i<2;i++){const a=arms[i],shoulder=new T.Vector3(a.side*.35,1.72,0),hand=hands[i],elbow=shoulder.clone().lerp(hand,.52).add(new T.Vector3(a.side*.1,-.15,.08));segment(a.upper,shoulder,elbow,.105);segment(a.fore,elbow,hand,.075);a.hand.position.copy(hand);a.hand.rotation.x=-.4;}
 const base=left.clone().add(new T.Vector3(0,-.15,0)),end=left.clone().add(new T.Vector3(0,1.8-pose*.4,1.7-pose*1.2));const releasePhase=Math.min(1,modeTime/.55);const castSwing=mode==='charging'?-chargeBlend*2.3:mode==='waiting'?-chargeBlend*2.3+Math.sin(releasePhase*Math.PI)*.45:0;end.z+=castSwing;end.y-=tension*.85+pull*.16;const points=[];for(let i=0;i<=14;i++){const u=i/14;const p=base.clone().lerp(end,u);p.z+=Math.sin(u*Math.PI)*tension*.45;p.y-=Math.sin(u*Math.PI)*tension*.3;points.push(p);}for(let i=0;i<14;i++){segment(rodSegments[i],points[i],points[i+1],1);}for(let i=0;i<guides.length;i++){guides[i].position.copy(points[(i+1)*2]).add(new T.Vector3(0,0,.035));guides[i].quaternion.copy(rodSegments[Math.min(13,(i+1)*2-1)].quaternion);}grip.position.copy(base).lerp(left,.55);grip.quaternion.copy(rodSegments[0].quaternion);spool.position.copy(left).add(new T.Vector3(-.08,-.11,.02));spool.rotation.z=reelPhase;crank.position.copy(spool.position).add(new T.Vector3(-.08,Math.sin(reelPhase)*.07,Math.cos(reelPhase)*.07));crank.rotation.x=reelPhase;g.updateMatrixWorld(true);rodTip.copy(points.at(-1));g.localToWorld(rodTip);hangAnchor.set(-.48,3.04,.85);g.localToWorld(hangAnchor);}
 refresh();update(.02,0,'idle');return {group:g,update,refresh,get tip(){return rodTip;},get hang(){return hangAnchor;},setOcean(on){g.position.y=on?.72:.3;},dispose(){g.traverse(o=>{if(o.isMesh){o.geometry.dispose();o.material.dispose();}});parent.remove(g);}};
